      "@id": "urn:solid-server:default:IdentityProviderFactory",
      "@type": "IdentityProviderFactory",
      "promptFactory": {
        "@id": "urn:solid-server:default:PromptFactory",
        "@type": "SequenceHandler",
        "handlers": [
          {
            "@type": "AccountPromptFactory",
