{
  "@context": "https://linkedsoftwaredependencies.org/bundles/npm/@solid/community-server/^7.0.0/components/context.jsonld",
  "comment": "DataAccessor configuration using a QuotaStrategy to enforce quota on the server.",
  "@graph": [
    {
      "comment": "DataAccessor that writes data to the disk with atomicity in mind",
      "@id": "urn:solid-server:default:AtomicFileDataAccessor",
      "@type": "AtomicFileDataAccessor",
      "resourceMapper": { "@id": "urn:solid-server:default:FileIdentifierMapper" },
      "rootFilePath": { "@id": "urn:solid-server:default:variable:rootFilePath" },
      "tempFilePath": "/.internal/tempFiles/"
    },

    {
      "comment": "Calculates the space already taken up by a resource",
      "@id": "urn:solid-server:default:SizeReporter",
      "@type": "FileSizeReporter",
      "fileIdentifierMapper": { "@id": "urn:solid-server:default:FileIdentifierMapper" },
      "rootFilePath": { "@id": "urn:solid-server:default:variable:rootFilePath" }
    },

    {
      "comment": "Validates the data being written to the server",
      "@id": "urn:solid-server:default:QuotaValidator",
      "@type": "QuotaValidator",
      "strategy": { "@id": "urn:solid-server:default:QuotaStrategy" }
    },

    {
      "comment": "Simple wrapper for another DataAccessor but adds validation",
      "@id": "urn:solid-server:default:ValidatingFileDataAccessor",
      "@type": "ValidatingDataAccessor",
      "accessor": { "@id": "urn:solid-server:default:AtomicFileDataAccessor" },
      "validator": { "@id": "urn:solid-server:default:QuotaValidator" }
    },
    {
      "comment": "Removes content-length metadata",
      "@id": "urn:solid-server:default:FileDataAccessor",
      "@type": "FilterMetadataDataAccessor",
      "accessor": { "@id": "urn:solid-server:default:ValidatingFileDataAccessor" },
      "filters": [
        {
          "@type": "FilterPattern",
          "predicate": "http://www.w3.org/2011/http-headers#content-length"
        }
      ]
    }
  ]
}

{
  "@context": "https://linkedsoftwaredependencies.org/bundles/npm/@solid/community-server/^7.0.0/components/context.jsonld",
  "import": [
    "css:config/storage/backend/data-accessors/file.json",
    "css:config/storage/backend/data-accessors/memory.json",
    "css:config/storage/backend/data-accessors/sparql-endpoint.json"
  ],
  "@graph": [
    {
      "comment": "A more complex example with 3 different stores being routed to.",
      "@id": "urn:solid-server:default:ResourceStore_Backend",
      "@type": "RoutingResourceStore",
      "rule": { "@id": "urn:solid-server:default:RouterRule" }
    },

    {
      "comment": [
        "Configure routing to send all requests containing /file/ to the file store, containing /memory/ to the memory store and /sparql/ to the sparql endpoint store.",
        "The root ACL and metadata resources will be stored in the sparql endpoint store."
      ],
      "@id": "urn:solid-server:default:RouterRule",
      "@type": "RegexRouterRule",
      "base": { "@id": "urn:solid-server:default:variable:baseUrl" },
      "rules": [
        {
          "@type": "RegexRule",
          "regex": "^/(\\.acl|\\.meta)?$",
          "store": { "@id": "urn:solid-server:default:SparqlResourceStore" }
        },
        {
          "@type": "RegexRule",
          "regex": "/file/",
          "store": { "@id": "urn:solid-server:default:FileResourceStore" }
        },
        {
          "@type": "RegexRule",
          "regex": "/memory/",
          "store": { "@id": "urn:solid-server:default:MemoryResourceStore" }
        },
        {
          "@type": "RegexRule",
          "regex": "/sparql/",
          "store": { "@id": "urn:solid-server:default:SparqlResourceStore" }
        }
      ]
    },

    {
      "@id": "urn:solid-server:default:FileResourceStore",
      "@type": "DataAccessorBasedStore",
      "identifierStrategy": { "@id": "urn:solid-server:default:IdentifierStrategy" },
      "auxiliaryStrategy": { "@id": "urn:solid-server:default:AuxiliaryStrategy" },
      "accessor": { "@id": "urn:solid-server:default:FileDataAccessor" },
      "metadataStrategy": { "@id": "urn:solid-server:default:MetadataStrategy" }
    },
    {
      "@id": "urn:solid-server:default:MemoryResourceStore",
      "@type": "DataAccessorBasedStore",
      "identifierStrategy": { "@id": "urn:solid-server:default:IdentifierStrategy" },
      "auxiliaryStrategy": { "@id": "urn:solid-server:default:AuxiliaryStrategy" },
      "accessor": { "@id": "urn:solid-server:default:MemoryDataAccessor" },
      "metadataStrategy": { "@id": "urn:solid-server:default:MetadataStrategy" }
    },
    {
      "comment": "SparqlDataAccessor only accepts quad objects so data to that route needs to be converted",
      "@id": "urn:solid-server:default:SparqlResourceStore",
      "@type": "RepresentationConvertingStore",
      "metadataStrategy": { "@id": "urn:solid-server:default:MetadataStrategy" },
      "options_inConverter": { "@id": "urn:solid-server:default:RepresentationConverter" },
      "options_inPreferences_type": {
        "RepresentationConvertingStore:_options_inPreferences_type_key": "internal/quads",
        "RepresentationConvertingStore:_options_inPreferences_type_value": 1
      },
      "source": {
        "@type": "DataAccessorBasedStore",
        "identifierStrategy": { "@id": "urn:solid-server:default:IdentifierStrategy" },
        "auxiliaryStrategy": { "@id": "urn:solid-server:default:AuxiliaryStrategy" },
        "accessor": { "@id": "urn:solid-server:default:SparqlDataAccessor" },
        "metadataStrategy": { "@id": "urn:solid-server:default:MetadataStrategy" }
      }
    }
  ]
}

